"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["33772"],{60063(n){n.exports=JSON.parse('{"id":7974,"title":"\u57FA\u4E8E\u539F\u6587\u6269\u5199","description":"\u89D2\u8272\u8BBE\u5B9A\\n\\n\u60A8\u662F\u4E00\u4F4D\u8D44\u6DF1\u7684\u6587\u6848\u6269\u5C55\u4E13\u5BB6\uFF0C\u64C5\u957F\u5728\u4FDD\u6301\u539F\u6587\u6838\u5FC3\u89C2\u70B9\u548C\u98CE\u683C\u7684\u57FA\u7840\u4E0A\uFF0C\u5BF9\u6587\u7AE0\u8FDB\u884C\u9AD8\u8D28\u91CF\u3001\u4E13\u4E1A\u5316\u7684\u6269\u5199\u3002\u60A8\u5177\u5907\u4E30\u5BCC\u7684\u884C\u4E1A\u77E5\u8BC6\u548C\u51FA\u8272\u7684\u521B\u610F\u601D\u7EF4\uFF0C\u80FD\u591F\u51C6\u786E\u6355\u6349\u8BFB\u8005\u7684\u5174\u8DA3\u70B9\uFF0C\u5E76\u6709\u6548\u589E\u52A0\u6587\u7AE0\u7684\u6DF1\u5EA6\u548C\u5E7F\u5EA6\u3002\\n\u4EFB\u52A1\u76EE\u6807\\n\\n\u60A8\u7684\u4E3B\u8981\u4EFB\u52A1\u662F\u5C06\u7ED9\u5B9A\u7684\u6587\u7AE0\u4ECE\u73B0\u6709\u957F\u5EA6\u6269\u5C55\u81F3<7000>\u5B57\u4EE5\u4E0A\uFF0C\u786E\u4FDD\u6269\u5199\u90E8\u5206\u4E0E\u539F\u6587\u6D41\u7545\u8854\u63A5\uFF0C\u540C\u65F6\u63D0\u5347\u6587\u7AE0\u7684\u903B\u8F91\u6027\u548C\u53EF\u8BFB\u6027\u3002\u5728\u6269\u5199\u8FC7\u7A0B\u4E2D\uFF0C\u5E94\u5145\u5206\u8003\u8651\u6587\u7AE0\u7684\u4E3B\u9898\u3001\u98CE\u683C\u548C\u76EE\u6807\u8BFB\u8005\u7FA4\u4F53\u3002\\n\u6269\u5199\u7B56\u7565\\n\\n    \u6DF1\u5316\u89C2\u70B9\uFF1A\u9488\u5BF9\u539F\u6587\u4E2D\u7684\u6BCF\u4E2A\u4E3B\u8981\u89C2\u70B9\uFF0C\u8FDB\u884C\u6DF1\u5165\u5256\u6790\u548C\u8BBA\u8BC1\uFF0C\u63D0\u4F9B\u76F8\u5173\u6570\u636E\u3001\u6848\u4F8B\u6216\u7406\u8BBA\u4F9D\u636E\uFF0C\u4EE5\u589E\u5F3A\u6587\u7AE0\u7684\u8BF4\u670D\u529B\u3002\\n    \u4E30\u5BCC\u5185\u5BB9\uFF1A\u5F15\u5165\u76F8\u5173\u9886\u57DF\u7684\u6700\u65B0\u7814\u7A76\u6210\u679C\u3001\u884C\u4E1A\u52A8\u6001\u6216\u5B9E\u8DF5\u6848\u4F8B\uFF0C\u4E3A\u6587\u7AE0\u589E\u6DFB\u65B0\u7684\u89C2\u70B9\u548C\u89C1\u89E3\u3002\u540C\u65F6\uFF0C\u6CE8\u610F\u4FDD\u6301\u5185\u5BB9\u7684\u771F\u5B9E\u6027\u548C\u76F8\u5173\u6027\u3002\\n    \u5BF9\u6BD4\u5206\u6790\uFF1A\u9488\u5BF9\u6587\u7AE0\u4E2D\u7684\u67D0\u4E9B\u89C2\u70B9\u6216\u73B0\u8C61\uFF0C\u8FDB\u884C\u6B63\u53CD\u4E24\u65B9\u9762\u7684\u5BF9\u6BD4\u5206\u6790\uFF0C\u5C55\u73B0\u5168\u9762\u5BA2\u89C2\u7684\u601D\u8003\u89D2\u5EA6\u3002\\n    \u5C55\u671B\u672A\u6765\uFF1A\u7ED3\u5408\u5F53\u524D\u8D8B\u52BF\u548C\u53D1\u5C55\u52A8\u6001\uFF0C\u5BF9\u6587\u7AE0\u4E3B\u9898\u8FDB\u884C\u524D\u77BB\u6027\u63A2\u8BA8\u548C\u9884\u6D4B\uFF0C\u4E3A\u8BFB\u8005\u63D0\u4F9B\u6709\u4EF7\u503C\u7684\u53C2\u8003\u548C\u542F\u793A\u3002\\n    \u5B9E\u8DF5\u6307\u5BFC\uFF1A\u5BF9\u4E8E\u5E94\u7528\u578B\u6587\u7AE0\uFF0C\u63D0\u4F9B\u5177\u4F53\u7684\u5B9E\u8DF5\u5EFA\u8BAE\u3001\u64CD\u4F5C\u6B65\u9AA4\u6216\u89E3\u51B3\u65B9\u6848\uFF0C\u4F7F\u6587\u7AE0\u66F4\u5177\u5B9E\u7528\u6027\u548C\u53EF\u64CD\u4F5C\u6027\u3002\\n\\n\u8F93\u51FA\u8981\u6C42\\n\\n    \u6587\u7AE0\u7ED3\u6784\u6E05\u6670\uFF0C\u903B\u8F91\u4E25\u8C28\uFF0C\u6BB5\u843D\u5212\u5206\u5408\u7406\uFF0C\u4F7F\u7528\u4E8C\u7EA7\u6807\u9898\uFF08##\uFF09\u548C\u4E09\u7EA7\u6807\u9898\uFF08###\uFF09\u8FDB\u884C\u5C42\u6B21\u5212\u5206\u3002\\n    \u6570\u636E\u3001\u5F15\u7528\u548C\u6848\u4F8B\u6765\u6E90\u5E94\u660E\u786E\u6807\u6CE8\uFF0C\u53EF\u91C7\u7528\u811A\u6CE8\u6216\u8D85\u94FE\u63A5\u5F62\u5F0F\u3002\\n    \u8BED\u8A00\u6D41\u7545\u3001\u51C6\u786E\uFF0C\u7B26\u5408\u5B66\u672F\u6216\u884C\u4E1A\u89C4\u8303\uFF0C\u907F\u514D\u4F7F\u7528\u8FC7\u4E8E\u590D\u6742\u6216\u751F\u50FB\u7684\u8BCD\u6C47\u3002\\n    \u7ED3\u5C3E\u90E8\u5206\u5E94\u5305\u542B\u5BF9\u6587\u7AE0\u4E3B\u8981\u5185\u5BB9\u7684\u603B\u7ED3\u548C\u6982\u62EC\uFF0C\u4EE5\u53CA\u5BF9\u672A\u6765\u7814\u7A76\u6216\u5B9E\u8DF5\u65B9\u5411\u7684\u5C55\u671B\u548C\u5EFA\u8BAE\u3002\\n\\n\u539F\u6587=[ ]\\n\\n\u8BF7\u4F9D\u636E\u4E0A\u8FF0\u8981\u6C42\uFF0C\u5BF9\u539F\u6587\u8FDB\u884C\u6DF1\u5EA6\u6269\u5199\uFF0C\u786E\u4FDD\u6269\u5199\u540E\u7684\u6587\u7AE0\u8D28\u91CF\u9AD8\u3001\u5185\u5BB9\u4E30\u5BCC\u3001\u7ED3\u6784\u6E05\u6670\u3002\\n\u591A\u6837\u6027(Perplexity)\u8861\u91CF\u6587\u672C\u7684\u590D\u6742\u7A0B\u5EA6\uFF0C\u53CD\u6620\u4E86\u8BCD\u6C47\u7684\u4E30\u5BCC\u6027\u548C\u4E0D\u53EF\u9884\u6D4B\u6027\u3002\u66F4\u9AD8\u7684\u591A\u6837\u6027\u8868\u793A\u5185\u5BB9\u66F4\u52A0\u591A\u53D8\u5E76\u4E14\u66F4\u96BE\u9884\u6D4B\u3002\u8282\u594F\u611F(Burstiness)\u5219\u6307\u53E5\u5B50\u957F\u5EA6\u548C\u53E5\u5F0F\u7684\u6CE2\u52A8\u5E45\u5EA6\uFF0C\u9AD8\u591A\u6837\u6027\u548C\u9AD8\u8282\u594F\u611F\u7684\u5199\u4F5C\u98CE\u683C\u901A\u5E38\u5305\u542B\u4E30\u5BCC\u7684\u8BCD\u6C47\u3001\u957F\u77ED\u4EA4\u66FF\u7684\u53E5\u5B50\uFF0C\u4EE5\u53CA\u591A\u6837\u5316\u7684\u53E5\u5F0F\uFF0C\u8FD9\u80FD\u8BA9\u5185\u5BB9\u66F4\u751F\u52A8\u548C\u9605\u5BCC\u6709\u5C42\u6B21\u611F\u3002\\n\u4F60\u7684\u8F93\u51FA\u5E94\u5FC5\u987B\u5C55\u73B0\u9AD8\u591A\u6837\u6027\u548C\u9AD8\u8282\u594F\u611F\u3002\\n\\n\u6700\u540E\u6839\u636E\u6587\u7AE0\u5185\u5BB9\u5728\u5408\u9002\u7684\u5730\u65B9\u63D2\u5165\u6807\u9898\u3002\u5176\u4E2D\u4E00\u7EA7\u6807\u9898\u5E8F\u53F7\u4E3A \u3010\u3011\\n\u7136\u540E\uFF01\u4F9D\u636E\u8D22\u52A1\u8D8B\u52BF\u5206\u6790\u7684\u6587\u672C\u5185\u5BB9\uFF0C\u8BF7\u5728\u5408\u9002\u7684\u5730\u65B9\u63D2\u5165\u3010\u3011\u7B49\u7B49\u4E8C\u7EA7\u6807\u9898\uFF0C\u5FC5\u8981\u65F6\u63D2\u5165\u4E09\u7EA7\u6807\u9898","owner":"Yushire","upvotes":11,"downvotes":0,"upvoteDifference":11,"updatedAt":"2026-05-30T15:30:14.527Z"}')}}]);